// packages/shared/src/segments.ts（已完成 slice1）
export type Segment =
  | { type: 'image'; path: string; name: string }  // ← 本 slice 消费
  | { type: 'text'; text: string }
  | { type: 'file'; path: string; lineRange?: [number, number] }
  | { type: 'skill'; name: string; location?: string }
  | { type: 'mention'; name: string }

// payload（renderer → main）
interface WriteTmpImagePayload {
  base64: string       // 无 data:image/png;base64, 前缀，纯 base64 字符串
  mimeType: string     // 'image/png' | 'image/jpeg' | 'image/gif' ...
  suggestedName?: string // 可选，截图无 name 时不传
}
// return（main → renderer）
interface WriteTmpImageResult {
  path: string  // 如 /var/folders/.../xyz-img-1780000000000-a3f.png
  name: string  // basename，如 xyz-img-1780000000000-a3f.png
}
